 app.innerHTML=`<div class="layout"><aside class="sidebar"><button class="brand-home" data-home aria-label="Till startsidan">${brandMarkup()}</button><div class="eyebrow">VOLONTÄRPORTALEN</div><nav class="nav">${navigationItems().map(([key,icon,label])=>`<button data-view="${key}" class="${view===key?'active':''}">${icon} &nbsp; ${label}</button>`).join('')}</nav><div class="side-bottom"><div class="profile"><span class="avatar">${esc(state.user.name.charAt(0))}</span><div><strong>${esc(state.user.name)}</strong><div class="small">${roleLabel(state.user.role)}</div></div></div><button class="link" data-action="logout">Logga ut ↗</button></div></aside><main><div class="topline"><span class="eyebrow">TILLSAMMANS FÖR KATTERNA</span>${state.portal?`<label class="portal-choice">Katthem<select id="portal-shelter">${state.portal.shelters.map(h=>`<option value="${esc(h.id)}" ${h.id===state.portal.selected?'selected':''}>${esc(h.name)}</option>`).join('')}</select></label>`:'<span class="badge">Volontärportalen</span>'}</div>${routineReminder()}${upcomingReminders()}${view==='board'?bulletinBoard():view==='staffing'&&admin?staffingPage():view==='info'?volunteerInfo():view==='schedule'?schedulePage():view==='members'&&state.members_enabled?membersPage():view==='mine'?myBookingsPage():view==='admin'&&admin?administrationPage():accountPage()}<footer>Katthemmet · Tack för att du gör plats för omtanke.</footer></main></div>`;
 app.querySelectorAll('[data-own-booking]').forEach(button=>button.onclick=async()=>{try{const home=button.dataset.home;if(home!==state.portal.selected){await api('portal/select','POST',{shelter:home});state=await api('state','GET',undefined,home)}else state=await api('state');render();slotDialog(Number(button.dataset.ownBooking))}catch(error){toast(error.message)}});
