 if(state.portal)app.querySelectorAll('a[href^="/api/"]').forEach(link=>{const u=new URL(link.getAttribute('href'),window.location.origin);u.searchParams.set('shelter',state.portal.selected);link.setAttribute('href',u.pathname+u.search)});
 if($('#portal-shelter'))$('#portal-shelter').onchange=async e=>{const selected=e.target.value,previous=state.portal.selected;try{await api('portal/select','POST',{shelter:selected});state.portal.selected=selected;state=await api('state');offset=0;filter='all';volunteerSearch='';volunteerFilter='all';render()}catch(err){state.portal.selected=previous;render();toast(err.message)}};
