 app.querySelectorAll('[data-intro-target]').forEach(button=>button.onclick=()=>{const target=button.dataset.introTarget;view='info';render();const section=$('#'+target);section?.focus({preventScroll:true});section?.scrollIntoView({block:'start',behavior:'smooth'})});
