function show(html){modal.innerHTML=html;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close())}
async function mutate(url,method,data,message){try{state=await api(url,method,data);if(modal.open)modal.close();if(view==='mine')ownBookings=null;render();if(view==='mine')loadMyBookings();toast(message)}catch(e){if(e.code==='OVERLAPPING_BOOKING'){confirmOverlapDialog(e.message,()=>mutate(url,method,{...data,confirmOverlap:true},message));return}const err=modal.querySelector('.error');if(err)err.textContent=e.message;else toast(e.message)}}
function confirmOverlapDialog(message,onConfirm){show(`<h2>Passens tider överlappar</h2><p class="info-text">${esc(message)}</p><p>Det går bra att delta i båda passen, till exempel morgonpass och öppet hus, om du kan vara kvar.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-overlap">Ja, bekräfta överlappningen</button></div>`);$('#confirm-overlap').onclick=async()=>{const button=$('#confirm-overlap');button.disabled=true;try{await onConfirm()}finally{if(button.isConnected)button.disabled=false}}}
function slotDialog(id){
 const s=state.slots.find(x=>x.id===id),admin=isAdmin(state.user),b=state.bookings.find(x=>x.slot_id===id&&x.user_id===state.user.id),canCancel=admin||new Date(s.date+'T'+s.start)-Date.now()>=86400000,ended=new Date(s.date+'T'+s.end)<=new Date();
 show(`<div class="eyebrow">${fmt(s.date,{weekday:'long',day:'numeric',month:'long'})}</div><h2>${esc(s.title)}</h2><p>${s.start}–${s.end} · ${esc(staffing(s))}</p><p class="experience-status ${s.green_booked>0?'has-experience':'needs-experience'}">${experienceLabel(s)}</p><p class="info-text muted">${esc(s.note)}</p>${cleaningNote(s.date)}${s.extra_info?`<section class="notice"><strong>Extra information</strong><p class="info-text">${esc(s.extra_info)}</p></section>`:''}${admin?`<h3>Bokade volontärer</h3>${state.bookings.filter(x=>x.slot_id===id).map(x=>`<div class="list-row"><span>${esc(x.name)}</span>${!s.cancelled?`<button class="danger" data-cancel="${x.id}">Avboka</button>`:''}</div>`).join('')||'<p class="small">Ingen bokad ännu.</p>'}${!past(s)&&!s.cancelled?`<label>Boka åt volontär<select id="book-user">${state.users.filter(u=>u.active&&!state.bookings.some(x=>x.slot_id===id&&x.user_id===u.id)).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><button id="admin-book">Boka vald volontär</button>`:''}`:''}<p class="error" role="alert"></p>${b&&!canCancel&&!s.cancelled?'<p class="notice">Mindre än 24 timmar kvar. Kontakta katthemmets bemanningsgrupp i Messenger för avbokning.</p>':''}<div class="dialog-actions">${admin&&!ended?`<button id="extra-info">${s.volunteer_meeting?'Information om träffen':'Extra information'}</button>`:''}${admin&&s.kind!=='open_house'&&!ended?`<button id="edit-slot">${s.cancelled?'Boka om':'Ändra / boka om'}</button>${!s.cancelled?'<button class="danger" id="cancel-slot">Ställ in</button>':''}`:''}${!past(s)&&!s.cancelled&&s.kind==='regular'?`<button id="recurring-book">${admin?'Boka återkommande åt vald volontär':'Boka återkommande'}</button>`:''}${admin&&!past(s)&&!s.cancelled&&s.kind==='regular'?'<button id="recurring-self">Boka återkommande</button>':''}${calendarLink(s)}<button data-close>Stäng</button>${!s.cancelled?(b?`<button class="danger" id="cancel" ${canCancel?'':'disabled'}>Avboka pass</button>`:!past(s)?'<button class="primary" id="book">Bekräfta bokning</button>':''):''}</div>`);

 if($('#recurring-self'))$('#recurring-self').onclick=()=>recurringForm(id,state.user.id);
 if($('#recurring-book'))$('#recurring-book').onclick=()=>{const uid=admin?Number($('#book-user')?.value):state.user.id;if(uid)recurringForm(id,uid);else modal.querySelector('.error').textContent='Välj en volontär att boka åt.'};
 if($('#book'))$('#book').onclick=()=>bookSlot(id);if($('#cancel'))$('#cancel').onclick=()=>mutate('bookings/'+b.id,'DELETE',null,'Passet är avbokat.');if($('#admin-book'))$('#admin-book').onclick=()=>{const uid=Number($('#book-user').value);if(uid)bookSlot(id,uid);else modal.querySelector('.error').textContent='Ingen bokningsbar volontär vald.'};modal.querySelectorAll('[data-cancel]').forEach(btn=>btn.onclick=()=>mutate('bookings/'+btn.dataset.cancel,'DELETE',null,'Bokningen är borttagen.'));
 if($('#extra-info'))$('#extra-info').onclick=()=>extraInfoForm(id);
 if($('#edit-slot'))$('#edit-slot').onclick=()=>eventForm(id);if($('#cancel-slot'))$('#cancel-slot').onclick=()=>cancelEvent(id);
}
function recurringForm(id,userId=state.user.id){const s=state.slots.find(s=>s.id===id),end=new Date(s.date+'T12:00');end.setDate(end.getDate()+41);const latest=state.slots.filter(x=>x.kind==='regular').map(x=>x.date).sort().pop()||s.date,max=[dateStr(end),latest].sort()[0];show(`<h2>Boka återkommande pass</h2><p>${esc(s.title)} · ${s.start}–${s.end} från ${fmt(s.date)}. ${isAdmin(state.user)?'För: '+esc(state.users.find(u=>u.id===userId)?.name||state.user.name):''}</p><p class="small">Boka samma veckodag och tid till ett valt slutdatum inom det öppna schemat. Serien fortsätter inte automatiskt efter slutdatum. Varje bokning kan sedan avbokas separat enligt vanliga regler.</p><form id="recurring-form"><label>Upprepa<select name="interval"><option value="1">Varje vecka</option><option value="2">Varannan vecka</option><option value="4">Var fjärde vecka</option></select></label><label>Till och med<input type="date" name="until" min="${s.date}" max="${max}" value="${max}" required></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Förhandsgranska</button></div></form>`);$('#recurring-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));recurringPreview({slotId:id,userId,interval:Number(data.interval),until:data.until})}}
async function recurringPreview(data){try{const plan=await api('bookings/recurring','POST',{...data,preview:true}),pending=plan.rows.filter(r=>r.status==='new'),labels={new:'Bokas',already:'Redan bokad – behålls',cancelled:'Inställt – hoppas över',missing:'Pass saknas – hoppas över'};show(`<h2>Bekräfta återkommande bokningar</h2><p>${pending.length} nya bokningar. Inställda och saknade pass hoppas över; befintliga bokningar behålls.</p>${plan.rows.map(r=>`<p>${fmt(r.date)} · ${r.start}–${r.end}: <strong>${labels[r.status]}</strong>${r.over_limit?' · Minst '+plan.recommended_limit+' anmälda':''}${r.overlap?' · Överlappar en annan bokning':''}</p>`).join('')}<form id="recurring-confirm">${pending.some(r=>r.over_limit)?`<label class="check-label"><input type="checkbox" name="limit" required> Jag vill boka även på pass med minst ${plan.recommended_limit} anmälda.</label>`:''}${pending.some(r=>r.overlap)?'<label class="check-label"><input type="checkbox" name="overlap" required> Jag bekräftar bokningarna som överlappar mina andra pass.</label>':''}<p class="error" role="alert"></p><div class="dialog-actions"><button type="button" id="recurring-back">Ändra urval</button><button type="button" data-close>Avbryt</button><button class="primary" ${pending.length?'':'disabled'}>Boka ${pending.length} pass</button></div></form>`);$('#recurring-back').onclick=()=>recurringForm(data.slotId,data.userId);$('#recurring-confirm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{state=await api('bookings/recurring','POST',{...data,key:plan.key,confirmOverLimit:Boolean(e.target.elements.limit?.checked),confirmOverlap:Boolean(e.target.elements.overlap?.checked)});modal.close();render();toast('De återkommande passen är bokade.')}catch(err){if(['INTRODUCTION_REQUIRED','INTRODUCTION_LIMIT','ENGAGEMENT_BLOCKED'].includes(err.code)){await explainBookingBlock(err);return}modal.querySelector('.error').textContent=err.message;button.disabled=false}}}catch(e){if(['INTRODUCTION_REQUIRED','INTRODUCTION_LIMIT','ENGAGEMENT_BLOCKED'].includes(e.code)){await explainBookingBlock(e);return}const error=modal.querySelector('.error');if(error)error.textContent=e.message;else toast(e.message)}}
function extraInfoForm(id){const s=state.slots.find(s=>s.id===id);show(`<h2>${s.volunteer_meeting?'Information om volontärsträffen':'Extra information på passet'}</h2><p>${esc(s.title)} · ${fmt(s.date)} · ${s.start}–${s.end}</p><form id="extra-info-form"><label>Extra information<textarea name="extra_info" rows="4" maxlength="1000" placeholder="Till exempel: Volontärsträff kl. 18 – välkommen!">${esc(s.extra_info||'')}</textarea></label><p class="small">Visas för volontärerna i schemat och i passets detaljer. Lämna tomt för att ta bort informationen. Bokade deltagare meddelas via den aktiverade e-postkopplingen.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara extra information</button></div></form>`);$('#extra-info-form').onsubmit=e=>{e.preventDefault();mutate('slots/'+id,'PATCH',Object.fromEntries(new FormData(e.target)),'Passinformationen har sparats.')}}
function newSlot(values={}){show(`<h2>Skapa extra pass</h2><p>Skapa ett engångspass eller samma pass återkommande till ett valt slutdatum. Volontärerna bokar sig sedan på respektive pass.</p><form id="slot-form"><input name="kind" type="hidden" value="regular"><label>Namn<input name="title" value="${esc(values.title||'Extra pass')}" required maxlength="100"></label><label>Första datum<input name="date" type="date" value="${values.date||dateStr(new Date())}" required></label><div class="form-grid"><label>Start<input name="start" type="time" value="${values.start||'13:00'}" required></label><label>Slut<input name="end" type="time" value="${values.end||'15:00'}" required></label></div><label>Upprepning<select name="interval" id="slot-repeat">${[[0,'En gång'],[1,'Varje vecka'],[2,'Varannan vecka'],[4,'Var fjärde vecka']].map(([v,label])=>`<option value="${v}" ${Number(values.interval||0)===v?'selected':''}>${label}</option>`).join('')}</select></label><label id="slot-until-label" ${Number(values.interval)?'':'hidden'}>Till och med<input name="until" id="slot-until" type="date" value="${values.until||''}" ${Number(values.interval)?'required':'disabled'}></label><p class="small">Återkommande extra pass kan skapas högst ett år framåt och förhandsgranskas innan de sparas. Redan befintliga pass med samma datum och tid samt inställda söndagspass hoppas över. Varje tillfälle ändras eller ställs in separat.</p><p class="notice">Minst 2 personer behövs, rekommenderat högst ${recommendedLimit()}. Söndagens socialiseringspass är 16–20, även första söndagen i månaden.</p><label>Information<textarea name="note" rows="2" maxlength="1000">${esc(values.note||'')}</textarea></label><label>Extra information (valfritt)<textarea name="extra_info" rows="2" maxlength="1000">${esc(values.extra_info||'')}</textarea></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary" id="create-extra-slot">${Number(values.interval)?'Förhandsgranska':'Skapa pass'}</button></div></form>`);$('#slot-repeat').onchange=e=>{const repeat=Number(e.target.value)>0;$('#slot-until-label').hidden=!repeat;$('#slot-until').disabled=!repeat;$('#slot-until').required=repeat;$('#create-extra-slot').textContent=repeat?'Förhandsgranska':'Skapa pass'};$('#slot-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.interval=Number(data.interval);if(data.interval)extraSlotPreview(data);else mutate('slots','POST',data,'Passet har skapats.')}}
async function extraSlotPreview(data){try{const plan=await api('slots/series','POST',{...data,preview:true}),count=plan.rows.filter(r=>r.status==='new').length;show(`<h2>Förhandsgranska extra pass</h2><p>${count} nya pass. Inga volontärer bokas automatiskt.</p><div class="series-preview">${plan.rows.map(r=>`<p>${fmt(r.date)} · ${r.start}–${r.end} · ${esc(r.title)}: <strong>${{new:'Skapas',exists:'Finns redan – hoppas över',cancelled:'Inställt enligt söndagsregeln – hoppas över'}[r.status]}</strong></p>`).join('')}</div><p class="error" role="alert"></p><div class="dialog-actions"><button id="edit-slot-series">Ändra urval</button><button data-close>Avbryt</button><button id="save-slot-series" class="primary" ${count?'':'disabled'}>Skapa ${count} pass</button></div>`);$('#edit-slot-series').onclick=()=>newSlot(data);$('#save-slot-series').onclick=async()=>{const button=$('#save-slot-series');button.disabled=true;try{state=await api('slots/series','POST',{...data,key:plan.key});modal.close();render();toast('De extra passen är skapade.')}catch(e){modal.querySelector('.error').textContent=e.message;button.disabled=false}}}catch(e){modal.querySelector('.error').textContent=e.message}}
function importUsers(){
 show(`<h2>Importera volontärer</h2><p class="small">UTF-8 CSV, högst 500 volontärer. Rubriker: namn;e-post;lösenord och valfritt grön (ja/nej). Lösenord ska ha 10–200 tecken. Befintliga e-postadresser ger ett fel; inga konton importeras då.</p><pre class="small">namn;e-post;lösenord;grön<br>Exempelperson;namn@exempel.se;BytDetta12345;nej</pre><form id="import-form"><label>CSV-fil<input id="import-file" type="file" accept=".csv,text/csv" required></label><label class="check-label"><input id="import-green" type="checkbox"> Grönmarkera alla i importen</label><p class="small">Utan detta val används kolumnen grön. Lämna inloggningsuppgifterna personligen; ingen e-post skickas.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Förhandsgranska</button></div></form>`);
 $('#import-form').onsubmit=async e=>{
  e.preventDefault();const btn=e.target.querySelector('button.primary');btn.disabled=true;
  try{
   const file=$('#import-file').files[0];if(!file||file.size>500000)throw Error('Välj en CSV-fil på högst 500 kB.');
   const payload={csv:await file.text(),green:$('#import-green').checked};
   const preview=await api('users/import-preview','POST',payload);
   show(`<h2>Importera ${preview.users.length} volontärer?</h2><p>${preview.users.filter(u=>u.green).length} grönmarkeras. Alla nya konton blir volontärer.</p><div class="import-preview">${preview.users.map(u=>`<div class="list-row ${u.green?'experienced-volunteer':''}"><span>${esc(u.name)}<br><span class="small">${esc(u.email)}</span></span>${u.green?'Grön':''}</div>`).join('')}</div><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button id="confirm-import" class="primary">Importera</button></div>`);
   $('#confirm-import').onclick=async()=>{const confirm=$('#confirm-import');confirm.disabled=true;await mutate('users/import','POST',payload,'Volontärerna har importerats.');if(modal.open)confirm.disabled=false};
  }catch(err){modal.querySelector('.error').textContent=err.message;btn.disabled=false}
 };
}


function upcomingReminders(){
 const now=Date.now(),soon=state.slots.filter(s=>s.mine&&!s.cancelled&&new Date(s.date+'T'+s.start)>now&&new Date(s.date+'T'+s.start)-now<=86400000);
 return soon.length?`<section class="notice reminder-notice" role="status"><strong>Påminnelse: dina pass inom nästa dygn</strong>${soon.map(s=>`<p>${esc(s.title)} · ${fmt(s.date)} kl. ${s.start}–${s.end} <button data-slot="${s.id}">Visa bokning</button></p>`).join('')}</section>`:'';
}
const adminSectionsOpen=new Set();
let staffingProblemsOnly=true;
function staffingWeekKey(date){const d=new Date(date+'T12:00');d.setDate(d.getDate()-(d.getDay()+6)%7);return dateStr(d)}
function staffingPage(now=new Date()){const limit=new Date(now);limit.setHours(0,0,0,0);limit.setDate(limit.getDate()+7);const all=state.slots.filter(s=>!s.cancelled&&new Date(s.date+'T'+s.start)>now&&new Date(s.date+'T'+s.start)<limit).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),problems=all.filter(s=>!staffed(s)||!s.green_booked),shown=staffingProblemsOnly?problems:all;return `<h1>Bemanning</h1><p class="muted">Närmaste 7 dagarna. Minst två personer och gärna minst en grönmarkerad person per pass.</p><div class="panel"><p><strong>${all.filter(s=>!staffed(s)).length}</strong> pass har färre än två bokade · <strong>${all.filter(s=>!s.green_booked).length}</strong> saknar grönmarkerad person.</p><button data-action="staffing-toggle">${staffingProblemsOnly?'Visa alla pass':'Visa endast pass som behöver stöd'}</button></div><section class="panel">${shown.length?shown.map((s,i)=>`${i===0||staffingWeekKey(shown[i-1].date)!==staffingWeekKey(s.date)?`<h2 class="staffing-week-divider">Vecka ${weekNumber(s.date)} · ${fmt(staffingWeekKey(s.date),{day:'numeric',month:'long',year:'numeric'})}</h2>`:''}<div class="list-row"><div><strong>${fmt(s.date,{weekday:'long',day:'numeric',month:'long'})} · ${esc(s.title)}</strong><p>${s.start}–${s.end} · ${esc(staffing(s))}</p><p class="experience-status ${s.green_booked>0?'has-experience':'needs-experience'}">${experienceLabel(s)}</p><p class="small">${state.bookings.filter(b=>b.slot_id===s.id).map(b=>esc(b.name)+(state.users.find(u=>u.id===b.user_id)?.green?' (grön)':'')).join(', ')||'Ingen bokad'}</p></div><button data-slot="${s.id}">Hantera pass</button></div>`).join(''):'<p>Inga pass behöver stöd under perioden.</p>'}</section><p class="small">Gröna volontärer har minst 10 genomförda pass och klar checklista. De är rutinerade personer att fråga. Admin och superadmin är också gröna. Det är ett planeringsstöd och hindrar inte bokning.</p>`}
function birthdayEntries(now=new Date()){const monday=new Date(now);monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-(monday.getDay()+6)%7);const entries=[];for(let day=0;day<7;day++){const date=new Date(monday);date.setDate(date.getDate()+day);for(const m of state.members||[])if(m.status!=='ended'&&m.birth_date?.slice(5)===dateStr(date).slice(5))entries.push({member:m,date:dateStr(date),today:dateStr(date)===dateStr(now)})}return entries}
function birthdayPanel(){const entries=birthdayEntries();return `<details class="admin-section" data-admin-section="birthdays" open><summary>Födelsedagar · ${entries.filter(e=>e.today).length} idag · ${entries.length} denna vecka</summary><div class="admin-section-body"><p>Innevarande vecka, måndag–söndag. Födelsedatum är frivilligt.</p>${entries.length?entries.map(e=>`<p>${e.today?'🎂 <strong>Idag:</strong> ':''}<button class="link" data-member-profile="${e.member.id}">${esc(e.member.name)}</button> · ${fmt(e.date,{weekday:'long',day:'numeric',month:'long'})}</p>`).join(''):'<p>Inga registrerade födelsedagar denna vecka.</p>'}</div></details>`}
